theorem Decomposition.mapAux_decompose_eq (hker : SetLike.IsHomogeneous ℳ f.ker) {a b : M}
    (h : f a = f b) :
    Decomposition.mapAux ℳ f (decompose ℳ a) = Decomposition.mapAux ℳ f (decompose ℳ b)

theorem Hochschild.merge_mem_grading {n : ℕ} (i : Fin n) {p : Fin (n + 1) → ℤ}
    {a : Fin (n + 1) → A} (ha : ∀ j, a j ∈ grading (p j)) (k : Fin n) :
    Hochschild.merge i a k ∈ grading (Fin.contractNth i.castSucc (· + ·) p k)

theorem hochschildD_mem {k : ℤ} {n : ℕ} {f : HochschildCochain R A M n}
    (hf : f ∈ hochschildCochains R A M k n) :
    hochschildD k n f ∈ hochschildCochains R A M k (n + 1)

theorem addHom_ext {N : Type*} [AddCommMonoid N] {f g : RegradeByDivision ℳ k r →+ N}
    (h : ∀ (q : ℤ) (m : M) (hm : m ∈ ℳ (q * k + r)), f (mk ℳ k r q m hm) = g (mk ℳ k r q m hm)) :
    f = g

theorem exists_isSimpleModule_add_of_isSemisimpleRing [IsSemisimpleRing R] {g : R}
    (hg : IsIdempotentElem g) (hN : Submodule.span R {g} ≠ ⊥) :
    ∃ s t : R, IsIdempotentElem s ∧ IsIdempotentElem t ∧ s * t = 0 ∧ t * s = 0 ∧ s + t = g ∧
      IsSimpleModule R (Submodule.span R {s}) ∧
      Submodule.span R {t} < Submodule.span R {g}

@[simp]
theorem toIdeal_spanSingleton {a : R} {i : ι} (ha : a ∈ 𝒜 i) :
    (spanSingleton 𝒜 ha).toIdeal = Ideal.span {a}

theorem decompose_mul_eq_zero {a b : ℤ} {x y : R}
    (hx : ∀ i, a < i → (decompose 𝒜 x i : R) = 0) (hy : ∀ j, b < j → (decompose 𝒜 y j : R) = 0)
    {n : ℤ} (hn : a + b < n) : (decompose 𝒜 (x * y) n : R) = 0

theorem comp_mem_coboundaries_left {X Y Z : C} {i j : ℤ} {f : X ⟶ Y} {g : Y ⟶ Z}
    (hf : f ∈ coboundaries (X ⟶ Y) i) (hg : g ∈ cocycles (Y ⟶ Z) j) :
    f ≫ g ∈ coboundaries (X ⟶ Z) (i + j)

theorem comp_mem_coboundaries_right {X Y Z : C} {i j : ℤ} {f : X ⟶ Y} {g : Y ⟶ Z}
    (hf : f ∈ cocycles (X ⟶ Y) i) (hg : g ∈ coboundaries (Y ⟶ Z) j) :
    f ≫ g ∈ coboundaries (X ⟶ Z) (i + j)

theorem comp_mem_cocycles {X Y Z : C} {i j : ℤ} {f : X ⟶ Y} {g : Y ⟶ Z}
    (hf : f ∈ cocycles (X ⟶ Y) i) (hg : g ∈ cocycles (Y ⟶ Z) j) :
    f ≫ g ∈ cocycles (X ⟶ Z) (i + j)

theorem decompose_mem_closure {T : Set M} (hT : ∀ x ∈ T, ∃ n, x ∈ grading (M := M) n) {x : M}
    (hx : x ∈ AddSubgroup.closure T) (n : ℤ) :
    (decompose (grading (M := M)) x n : M) ∈ AddSubgroup.closure T

theorem comp_assoc {Q ω : Type*} [AddCommGroup Q] [SetLike ω Q] {𝒬 : ι → ω} {m n p : ι}
    (h : GradedHom 𝒪 𝒬 p) (g : GradedHom 𝒩 𝒪 n) (f : GradedHom ℳ 𝒩 m) :
    HEq ((h.comp g).comp f) (h.comp (g.comp f))

theorem toAddMonoidHom_comp_assoc {Q ω : Type*} [AddCommGroup Q] [SetLike ω Q] {𝒬 : ι → ω}
    {m n p : ι} (h : GradedHom 𝒪 𝒬 p) (g : GradedHom 𝒩 𝒪 n) (f : GradedHom ℳ 𝒩 m) :
    ((h.comp g).comp f).toAddMonoidHom = (h.comp (g.comp f)).toAddMonoidHom

theorem HasDegree.comp [AddSemigroup ι] {ℳ : ι → σ} {𝒩 : ι → τ} {𝒪 : ι → υ} {m n : ι}
    {f : M →+ N} {g : N →+ P} (hf : HasDegree ℳ 𝒩 m f) (hg : HasDegree 𝒩 𝒪 n g) :
    HasDegree ℳ 𝒪 (m + n) (g.comp f)

theorem of_congr {i j : ℤ} (h : i = j) {f : Cochain A M N i} {g : Cochain A M N j}
    (hfg : ∀ x, f x = g x) :
    (DirectSum.of (fun n => Cochain A M N n) i f : HOM A M N) = DirectSum.of _ j g

theorem of_congr {i j : ℤ} (h : i = j) {f : Cochain M N i} {g : Cochain M N j}
    (hfg : ∀ X x, f.app X x = g.app X x) :
    (DirectSum.of (fun n => Cochain M N n) i f : HOM M N) = DirectSum.of _ j g

theorem postcompCochain_congr {k' : ℤ} (h : k = k') {z : Cochain N N' k} {z' : Cochain N N' k'}
    (hz : ∀ X x, z.app X x = z'.app X x) (w : HOM P N) :
    postcompCochain z w = postcompCochain z' w

theorem koszulTwist_apply_of_mem (f : A →+ M →+ N) {i j : ℤ} {a : A} {m : M}
    (ha : a ∈ grading i) (hm : m ∈ grading j) :
    koszulTwist f a m = koszulSign (i * j) • f a m

theorem yonedaCochainApp_comp {n : ℤ} {m : M.obj X} (hm : m ∈ grading n) {Y Z : C} {i : ℤ}
    {f : Y ⟶ Z} (hf : f ∈ grading i) (h : X ⟶ Y) :
    yonedaCochainApp m Z (h ≫ f) = koszulSign (n * i) • (f • yonedaCochainApp m Y h)

theorem yonedaCochainApp_of_mem {n : ℤ} {m : M.obj X} (hm : m ∈ grading n) {Y : C} {i : ℤ}
    {h : X ⟶ Y} (hh : h ∈ grading i) :
    yonedaCochainApp m Y h = koszulSign (i * n) • (h • m)

@[simp]
theorem ofElement_smul_gen {n : ℤ} (y : N.obj X) (hy : y ∈ grading (k + n)) {Y : C}
    (f : X ⟶ Y) : (hg.ofElement y hy).app Y (f • g) = twist n (e.val ≫ f) • y

theorem orthogonal_listSum {e : Idempotent X} {l : List (Idempotent X)}
    (he : ∀ f ∈ l, e.Orthogonal f) (hl : l.Pairwise Orthogonal) :
    e.val ≫ (listSum l hl).val = 0 ∧ (listSum l hl).val ≫ e.val = 0

theorem apply_eq_of_sub_directSumShift_eq {a : DirectSum ℕ fun n => (K ⟶ X n)} {n : ℕ}
    {w : K ⟶ X n} (h : a - directSumShift f a = DirectSum.of _ n w) {m : ℕ} (hnm : n ≤ m) :
    a m = w ≫ (Functor.ofSequence f).map (homOfLE hnm)

theorem mk_mem_closure_of_forall (S : ObjectProperty T) {X : T}
    (hX : ∀ P : ObjectProperty T, P.IsTriangulated → P.IsClosedUnderIsomorphisms → S ≤ P → P X) :
    mk X ∈ AddSubgroup.closure {x | ∃ Y, S Y ∧ mk Y = x}

theorem nonempty_homotopy_of_Q_map_eq (hK : IsPerfectComplex K) {g₁ g₂ : K ⟶ L}
    (h : _root_.DerivedCategory.Q.map g₁ = _root_.DerivedCategory.Q.map g₂) :
    Nonempty (Homotopy g₁ g₂)

theorem exists_iso_obj_of_retract {C D : Type*} [Category C] [Category D]
    [IsIdempotentComplete C] (F : C ⥤ D) [F.Full] [F.Faithful] {X : D} {M : C}
    (h : Retract X (F.obj M)) : ∃ (M' : C) (_ : Retract M' M), Nonempty (X ≅ F.obj M')

theorem lift_mem (f : X → B) (hf : ∀ x, f x ∈ grading (S.deg x)) {n : ℤ}
    {a : FreeAlgebra R X} (ha : a ∈ freeGrading R S.deg n) :
    FreeAlgebra.lift R f a ∈ grading n

theorem freeDeriv_mem (hδ : ∀ x, δ x ∈ freeGrading R deg (deg x + 1)) {n : ℤ}
    {a : FreeAlgebra R X} (ha : a ∈ freeGrading R deg n) :
    freeDeriv deg δ a ∈ freeGrading R deg (n + 1)

theorem smul_mem {p q : ℤ × ZMod 2} {a : A} {m : M}
    (ha : a ∈ grading A p) (hm : m ∈ grading M q) :
    a • m ∈ grading M (p + q)

theorem IsAlt.eq_zero_of_apply_eq {n : ℕ} {f : MCochain R 𝔤 (n + 1)} (hf : IsAlt f) {x : 𝔤}
    (hx : ∀ w : Fin n → 𝔤, f (Fin.cons x w) = 0) (v : Fin (n + 1) → 𝔤) (k : Fin (n + 1))
    (hk : v k = x) : f v = 0

theorem hom_ext {M : ModuleCat.{u} R} {n : ℤ} {f g : (K ⊗ L).X n ⟶ M}
    (hfg : ∀ (p q : ℤ) (h : p + q = n) (x : K.X p) (y : L.X q),
      f (tmul K L h x y) = g (tmul K L h x y)) : f = g

theorem tensor_unit_hom_ext {N : ModuleCat.{u} R} {n : ℤ}
    {f g : (K ⊗ 𝟙_ (CochainComplex (ModuleCat.{u} R) ℤ)).X n ⟶ N}
    (hfg : ∀ x : K.X n, f (tmul K _ (add_zero n) x (unitOne R)) =
      g (tmul K _ (add_zero n) x (unitOne R))) : f = g

theorem unit_tensor_hom_ext {N : ModuleCat.{u} R} {n : ℤ}
    {f g : (𝟙_ (CochainComplex (ModuleCat.{u} R) ℤ) ⊗ K).X n ⟶ N}
    (hfg : ∀ x : K.X n, f (tmul _ K (zero_add n) (unitOne R) x) =
      g (tmul _ K (zero_add n) (unitOne R) x)) : f = g
